"""Reproducible, evidence-aware screening report generation."""
from __future__ import annotations
from datetime import datetime,timezone
from typing import Any
from app.services import gherproof_screening_service as evidence

def build_report()->dict[str,Any]:
    status=evidence.screening_status();scene_data=evidence.scenes();registry=evidence.registry()
    s1=[s for s in scene_data['scenes'] if s['sensor']=='Sentinel-1'];s2=[s for s in scene_data['scenes'] if s['sensor']=='Sentinel-2']
    return {'report_type':'evidence_aware_regional_screening_summary','generated_at_utc':datetime.now(timezone.utc).isoformat(),'study_area':{'name':'Sujatpur / six-village provisional regional search extent','status':'provisional_geographic_reference','authoritative_village_or_enclosure_boundary':False},'date_range':{'sentinel1':sorted({x['acquisition_date'] for x in s1}),'sentinel2':sorted({x['acquisition_date'] for x in s2}),'reported_event_date':'2026-01-14'},'reported_incident':{'status':'news_reported_event_not_independently_verified','evidence_id':'reported-event-2026-01-14'},'satellite_observations':s1,'optical_observations':s2,'pre_post_pairs':scene_data['pre_post_eligibility'],'model_predictions':{'status':'exploratory','models':['scratch','pretrained'],'selected_model':None,'evidence_ids':[r['evidence_id'] for r in evidence.records('model_prediction') if r.get('evidence_id','').startswith('prediction-')]},'model_disagreement':{'status':'exploratory','evidence_ids':[r['evidence_id'] for r in evidence.records('model_prediction') if r.get('evidence_id','').startswith('disagreement-')],'interpretation':'disagreement is model inconsistency, not measured error or water truth'},'optical_reference':{'status':'under_review','human_label_status':status['local_validation_status'],'label_slots':status['human_label_slots'],'completed_labels':status['human_labels_completed']},'coverage':evidence.coverage(),'registry':{'record_count':registry.get('record_count'),'category_counts':registry.get('category_counts')},'model_readiness':status['model_readiness'],'impact_quantification':status['impact_quantification'],'limitations':status['limitations'],'methodology_note':'This report indexes observations and derived layers only. It does not infer verified flood extent, village impact, infrastructure failure, breach causality, crop loss or financial loss.'}

def build_markdown(report:dict|None=None)->str:
    r=report or build_report();lines=['# DHARA — Evidence-Aware Regional Screening Summary','',f"Generated: {r['generated_at_utc']}",'', '## Evidence status','',f"- Study geography: {r['study_area']['status']} (not authoritative village or enclosure boundary).",f"- Sentinel-1 RTC acquisitions: {len(r['satellite_observations'])}; dates: {', '.join(sorted({x['acquisition_date'] for x in r['satellite_observations']})) or 'none'}.",f"- Sentinel-2 optical dates: {', '.join(sorted({x['acquisition_date'] for x in r['optical_observations']})) or 'none'}.",f"- Local human reference labels: {r['optical_reference']['completed_labels']} / {r['optical_reference']['label_slots']}.",f"- Model readiness: `{r['model_readiness']}`; selected model: none.",f"- Impact quantification: **{r['impact_quantification']}**.",'','## Interpretation restrictions','']
    lines.extend(f'- {x}' for x in r['limitations']);lines.extend(['','No predicted pixel totals in this report are presented as measured flood area. Model predictions and optical indicators are kept separate from satellite measurements and reported event claims.',''])
    return '\n'.join(lines)
